<?php
require dirname(__DIR__,2).'/app/admin_view.php';admin_header('overview','Service controller');
$slug=preg_replace('/[^a-z0-9-]/','',(string)($_GET['slug']??''));?>
<div class="toolbar"><a class="btn" href="/admin/">← Admin overview</a><span class="muted">Every customer service page has its own controller and analytics view.</span></div>
<div id="service-content"><p class="muted">Loading service analytics…</p></div>
<script>
const slug=<?=json_encode($slug)?>,root=document.getElementById('service-content'),notice=document.getElementById('notice');let data=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function load(){const r=await fetch('/api/admin-service.php?slug='+encodeURIComponent(slug),{credentials:'same-origin',cache:'no-store'});const d=await r.json();if(!r.ok){root.textContent=d.error||'Unable to load this service.';return;}data=d;draw();}
function draw(){const p=data.page,s=data.stats,services=data.services;const max=Math.max(1,...data.trend.map(x=>Number(x.orders_count)));const bars=data.trend.map((x,i)=>{const h=Math.max(4,Number(x.orders_count)/max*140);return `<rect x="${i*22+6}" y="${160-h}" width="13" height="${h}" rx="3" fill="#6366f1"><title>${esc(x.day)} · ${x.orders_count} orders · £${Number(x.value_total).toFixed(2)}</title></rect>`;}).join('');
root.innerHTML=`<div class="toolbar"><span class="service-icon">${esc(p.icon)}</span><h2 style="margin:0">${esc(p.name)}</h2><span class="badge">${p.active?'Visible on user dashboard':'Hidden from user dashboard'}</span></div><div class="stats"><div class="stat"><span>Total orders</span><strong>${Number(s.total)}</strong></div><div class="stat"><span>Income after refunds</span><strong>£${Number(s.income).toFixed(2)}</strong></div><div class="stat"><span>Requests to review</span><strong>${Number(s.pending)}</strong></div><div class="stat"><span>In progress</span><strong>${Number(s.processing)}</strong></div><div class="stat"><span>Completed / publications</span><strong>${Number(s.completed)}</strong></div><div class="stat"><span>Customers</span><strong>${Number(s.customers)}</strong></div><div class="stat"><span>Average order</span><strong>£${Number(s.average_value).toFixed(2)}</strong></div></div><div class="split"><section class="panel"><h2>Orders and publication activity · last 30 days</h2><svg class="chart" viewBox="0 0 680 180" preserveAspectRatio="none"><line x1="0" y1="160" x2="680" y2="160" stroke="#ffffff20"/>${bars}</svg><p class="muted">Bars show orders received per day. Completed orders are the published or delivered count for this service.</p></section><section class="panel"><h2>Service page controls</h2><div class="form-grid"><div class="field"><label>Dashboard label</label><input class="input" id="page-name" value="${esc(p.name)}"></div><div class="field"><label>Dashboard icon</label><input class="input" id="page-icon" maxlength="80" value="${esc(p.icon)}"></div><div class="field" style="grid-column:1/-1"><label>Dashboard description</label><textarea id="page-description" maxlength="500">${esc(p.description)}</textarea></div><label><input type="checkbox" id="page-active" ${p.active?'checked':''}> Show this service on user dashboard</label><button class="btn primary" onclick="savePage()">Save service page</button></div></section></div><section class="panel"><h2>Requests, orders, and publications</h2>${data.orders.length?`<table><thead><tr><th>Order</th><th>Customer</th><th>Request details</th><th>Amount</th><th>Status</th><th>Update request</th></tr></thead><tbody>${data.orders.map(o=>{let details='';try{details=JSON.stringify(typeof o.details==='string'?JSON.parse(o.details):o.details||{});}catch{}return `<tr><td>#${o.id}<br><small class="muted">${esc(o.created_at)}</small></td><td>${esc(o.customer)}<br><small class="muted">${esc(o.email)}</small></td><td><strong>${esc(o.service)}</strong><br>${esc(o.description)}<br><small class="muted">${esc(details)}</small></td><td>£${Number(o.amount).toFixed(2)}</td><td><span class="badge">${esc(o.status)}</span></td><td><select class="input" id="status-${o.id}">${['pending','processing','completed','rejected','cancelled'].map(st=>`<option value="${st}" ${st===o.status?'selected':''}>${st}</option>`).join('')}</select><textarea class="input" id="note-${o.id}" maxlength="4000" placeholder="Customer-visible update">${esc(o.admin_note||'')}</textarea><button class="btn small" onclick="saveOrder(${o.id})">Save update</button></td></tr>`;}).join('')}</tbody></table>`:'<p class="empty">No requests or publications have been submitted for this service.</p>'}</section><section class="panel"><h2>Related catalog prices</h2>${services.length?`<table><thead><tr><th>Catalog item</th><th>Price GBP</th><th>Active</th><th>Save</th></tr></thead><tbody>${services.map(x=>`<tr><td>${esc(x.name)}<br><small class="muted">${esc(x.slug)} · ${esc(x.pricing_mode)}</small></td><td><input class="input short" id="price-${x.id}" type="number" min="0" step="0.01" value="${Number(x.price).toFixed(2)}"></td><td><input type="checkbox" id="active-${x.id}" ${x.active?'checked':''}></td><td><button class="btn small" onclick="savePrice(${x.id})">Save price</button></td></tr>`).join('')}</tbody></table>`:'<p class="empty">This service page has no catalog items mapped to it yet.</p>'}</section>`;}
async function send(action,values){const r=await fetch('/api/admin-service.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':data.csrf},body:JSON.stringify({action,slug,...values})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Unable to save changes.');notice.textContent='Saved.';notice.className='notice';await load();}
function savePage(){send('page_update',{name:document.getElementById('page-name').value,icon:document.getElementById('page-icon').value,description:document.getElementById('page-description').value,active:document.getElementById('page-active').checked}).catch(e=>{notice.textContent=e.message;notice.className='notice error';});}
function saveOrder(id){send('order_update',{id,status:document.getElementById('status-'+id).value,note:document.getElementById('note-'+id).value}).catch(e=>{notice.textContent=e.message;notice.className='notice error';});}
function savePrice(id){send('service_update',{id,price:document.getElementById('price-'+id).value,active:document.getElementById('active-'+id).checked}).catch(e=>{notice.textContent=e.message;notice.className='notice error';});}
load();
</script>
<?php admin_footer(); ?>
